using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Spreadsheet;
using Naide.LevelManager.Domain;
using Naide.LevelManager.Infrastructure;
using Xunit;
namespace Naide.LevelManager.Tests;
public class R22Phase2Tests
{
 static byte[] Associations(byte[] original,params string[][] rows){using var memory=new MemoryStream();memory.Write(original);memory.Position=0;using(var doc=SpreadsheetDocument.Open(memory,true)){var part=doc.WorkbookPart!;var sheet=part.Workbook!.Sheets!.Elements<Sheet>().Single(s=>s.Name=="罐组关联");var ws=(WorksheetPart)part.GetPartById(sheet.Id!);var data=ws.Worksheet!.GetFirstChild<SheetData>()!;foreach(var row in data.Elements<Row>().Skip(1).ToArray())row.Remove();foreach(var values in rows)data.Append(new Row(values.Select(v=>new Cell{DataType=CellValues.InlineString,InlineString=new InlineString(new Text(v))})));ws.Worksheet.Save();}return memory.ToArray();}
 static SystemConfiguration Grouped(){var c=Fixtures.Configuration();return c with{Groups=[new(){Name="一罐区",TankIds=[c.Tanks[0].Id]},new(){Name="柴油罐组",TankIds=[c.Tanks[0].Id]}]};}
 [Fact]public void SeparateGroupSheetRoundTripsMultipleMemberships(){var c=Grouped();var bytes=TankConfigurationExcel.Export(c,[]);using var doc=SpreadsheetDocument.Open(new MemoryStream(bytes),false);var part=doc.WorkbookPart!;var sheet=part.Workbook!.Sheets!.Elements<Sheet>().Single(s=>s.Name=="罐组关联");var ws=(WorksheetPart)part.GetPartById(sheet.Id!);Assert.Equal(3,ws.Worksheet!.Descendants<Row>().Count());Assert.Equal(2,ws.Worksheet.Descendants<DataValidation>().Count());var preview=TankConfigurationExcel.Preview(bytes,c,[]);Assert.Empty(preview.Issues);Assert.Equal(c.Groups.Select(g=>g.TankIds.Single()),preview.Configuration.Groups.Select(g=>g.TankIds.Single()));}
 [Fact]public void GroupSheetReplacesOnlyListedTankAndExplicitBlankClears(){var c=Grouped();var bytes=TankConfigurationExcel.Export(c,[]);var clear=TankConfigurationExcel.Preview(Associations(bytes,[c.Tanks[0].Code,""]),c,[]);Assert.Empty(clear.Issues);Assert.All(clear.Configuration.Groups,g=>Assert.Empty(g.TankIds));var omit=TankConfigurationExcel.Preview(Associations(bytes),c,[]);Assert.Empty(omit.Issues);Assert.All(omit.Configuration.Groups,g=>Assert.Contains(c.Tanks[0].Id,g.TankIds));var one=TankConfigurationExcel.Preview(Associations(bytes,[c.Tanks[0].Code,c.Groups[0].Id.ToString()]),c,[]);Assert.Empty(one.Issues);Assert.Single(one.Configuration.Groups[0].TankIds);Assert.Empty(one.Configuration.Groups[1].TankIds);}
 [Fact]public void DuplicateUnknownAndMixedBlankGroupRowsReject(){var c=Grouped();var bytes=TankConfigurationExcel.Export(c,[]);Assert.NotEmpty(TankConfigurationExcel.Preview(Associations(bytes,[c.Tanks[0].Code,c.Groups[0].Id.ToString()],[c.Tanks[0].Code,c.Groups[0].Id.ToString()]),c,[]).Issues);Assert.NotEmpty(TankConfigurationExcel.Preview(Associations(bytes,[c.Tanks[0].Code,"未知罐组"]),c,[]).Issues);Assert.NotEmpty(TankConfigurationExcel.Preview(Associations(bytes,["T-MISSING",c.Groups[0].Id.ToString()]),c,[]).Issues);Assert.NotEmpty(TankConfigurationExcel.Preview(Associations(bytes,[c.Tanks[0].Code,""],[c.Tanks[0].Code,c.Groups[0].Id.ToString()]),c,[]).Issues);}
 [Fact]public void OldFormat2GroupColumnStillImports(){var c=Grouped();using var stream=new MemoryStream();stream.Write(TankConfigurationExcel.Export(c,[]));stream.Position=0;using(var doc=SpreadsheetDocument.Open(stream,true)){var part=doc.WorkbookPart!;WorksheetPart Get(string name)=>(WorksheetPart)part.GetPartById(part.Workbook!.Sheets!.Elements<Sheet>().Single(s=>s.Name==name).Id!);var ws=Get("罐体与通讯");foreach(var row in ws.Worksheet!.Descendants<Row>())row.Append(new Cell{DataType=CellValues.InlineString,InlineString=new InlineString(new Text(row.RowIndex!.Value==1?"所属罐组编号（分号分隔）":string.Join(';',c.Groups.Select(g=>g.Id))))});ws.Worksheet.Save();var info=Get("填写说明");foreach(var text in info.Worksheet!.Descendants<Text>().Where(t=>t.Text is "TANK-CONFIG-3" or "TANK-CONFIG-4"))text.Text="TANK-CONFIG-2";info.Worksheet.Save();}var result=TankConfigurationExcel.Preview(stream.ToArray(),c,[]);Assert.Empty(result.Issues);Assert.All(result.Configuration.Groups,g=>Assert.Single(g.TankIds));}
 [Fact]public void FixedAxisRejectsInvertedBoundsAndNegativeSpan(){var c=Fixtures.Configuration();var t=c.Tanks[0];var good=new TrendAxisPreferences{Mode=TrendAxisMode.Fixed,Minimum=1,Maximum=2,MinimumSpan=1};SystemConfiguration With(TrendAxisPreferences a)=>c with{Tanks=[t with{Trends=t.Trends with{Axes=new Dictionary<TrendQuantity,TrendAxisPreferences>{{TrendQuantity.Level,a}}}}]};Assert.Empty(ConfigurationRules.Validate(With(good)));Assert.Contains(ConfigurationRules.Validate(With(good with{Maximum=0})),i=>i.Message.Contains("纵轴"));Assert.Contains(ConfigurationRules.Validate(With(good with{MinimumSpan=-1})),i=>i.Message.Contains("纵轴"));}
 [Fact]public void CapacityAndConfigurationExportsHaveLightThinBorders(){var files=new[]{CapacityExcel.Export(new(){Number="T",Name="表",Points=[new(0,0),new(100,1)]}),TankConfigurationExcel.Export(Grouped(),[])};foreach(var file in files){using var doc=SpreadsheetDocument.Open(new MemoryStream(file),false);var styles=doc.WorkbookPart!.WorkbookStylesPart!.Stylesheet!;Assert.Contains(styles.Borders!.Elements<Border>(),b=>b.LeftBorder?.Style?.Value==BorderStyleValues.Thin&&b.LeftBorder.Color?.Rgb?.Value=="FFD9E1E6");Assert.All(styles.CellFormats!.Elements<CellFormat>(),f=>Assert.True(f.ApplyBorder?.Value));Assert.Empty(new DocumentFormat.OpenXml.Validation.OpenXmlValidator().Validate(doc));}}
}
